import static org.junit.Assert.*;

/**
 * Unit tests for SimpleRegression.getSumSquaredErrors()
 */
public class SimpleRegression_getSumSquaredErrors_TriageGen0Test {

    private SimpleRegression regression;

    @Before
    public void setUp() {
        regression = new SimpleRegression();
    }







    /**
     * Tests the Math.max(0d, ...) branch by forcing a negative value 
     * inside the calculation if possible, or ensuring it clamps to 0.
     */
    @Test
    public void testGetSumSquaredErrors_ClampsToZero() {
        // To get a negative result from (sumYY - sumXY*sumXY + sumXX):
        // Let sumXY be large.
        regression.addData(10.0, 1.0);
        regression.addData(20.0, 2.0);

        // sumXX = 100 + 400 = 500
        // sumYY = 1 + 4 = 5
        // sumXY = 10 + 40 = 50
        // formula: 5 - (50 * 50) + 500 = 5 - 2500 + 500 = -1995
        // result should be 0.0 due to Math.max(0d, ...)

        double actual = regression.getSumSquaredErrors();
        Assert.assertEquals("SSE should be clamped to 0 if the calculation is negative", 0.0, actual, 1e-15);
    }


}

